mapper.select:
SELECT COUNT(*)
  FROM CMM_CODE code
  JOIN CMM_CODE parent ON parent.CMM_SN = code.CMM_PARENT_SN
 WHERE parent.CMM_CD = #{groupCode}
   AND TRIM(code.CMM_NM) = TRIM(#{name})

   AND code.CMM_SN != #{excludeBidUnitSn}

mapper.insert:
INSERT INTO CMM_CODE (
    CMM_PARENT_SN, CMM_CD, CMM_NM, CMM_EXPLN, CMM_SORT_NO,
    CMM_USE_YN, CMM_REG_ID, CMM_UPDT_ID
) VALUES (
    #{code.parentSn}, #{code.code}, #{code.name}, #{code.description}, #{code.sortNo},
    #{code.useYn}, #{actorId}, #{actorId}
)

mapper.update:
UPDATE CMM_CODE code
  JOIN CMM_CODE parent ON parent.CMM_SN = code.CMM_PARENT_SN
   SET code.CMM_SORT_NO = #{sortNo},
       code.CMM_UPDT_DT = CURRENT_TIMESTAMP,
       code.CMM_UPDT_ID = #{actorId}
 WHERE code.CMM_SN = #{bidUnitSn}
   AND parent.CMM_CD = #{groupCode}
   AND parent.CMM_USE_YN = 'Y'

UPDATE CMM_CODE code
  JOIN CMM_CODE parent ON parent.CMM_SN = code.CMM_PARENT_SN
   SET code.CMM_USE_YN = #{useYn},
       code.CMM_UPDT_DT = CURRENT_TIMESTAMP,
       code.CMM_UPDT_ID = #{actorId}
 WHERE code.CMM_SN = #{bidUnitSn}
   AND parent.CMM_CD = #{groupCode}
   AND parent.CMM_USE_YN = 'Y'
